#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// mcd — the minecraft-design toolkit CLI. Pure Node 20+, no install step.
//
//   mcd light   <file.nbt> --rooms rooms.json [--only name,...] | --y <feet y>   light-level map (text; --json summary)
//   mcd rooms   <file.nbt> --rooms rooms.json [--out rooms.png] [--only name,...]   a look into every room
//   mcd render  <file.nbt> [--out sheet.png] [--front n|s|e|w] [--ground y] [--cut y]
//               [--eye x,y,z --look x,y,z [--label text]]... [--view "name:x,y,z->x,y,z"]... [--version v] [--tiles dir]
//               (--view: a named exterior camera with sun shadows, e.g. the iconic view from downstream)
//               [--closeups]  adds a glance tile (street view at 320 px) and close-ups at >= 12 px/block: entrance,
//               eave band, each facade's busiest region, small features (signs, banners, lanterns, finials)
//   mcd zoom    <file.nbt> --at x,y,z [--radius r] [--from n|s|e|w] [--out zoom.png]   framed close-up of one spot
//   mcd diff    <before.nbt> <after.nbt> [--png out.png] [--json] [--fail-empty]   change census (added/removed/replaced
//               by block, boxes, faces shown on, hidden cells); --png: pixels changed per view + before/after crops
//   mcd palette <file.nbt> [--json]   roles (walls/trim/roof/base/openings/accents) with measured tone; flags same-tone
//               roof, invisible trim, outlier blocks, > 3 accent families, dark-on-dark detail, each with a suggestion
//   mcd compare <before.nbt> <after.nbt> [--out compare.png] [render options]
//   mcd check   <file.nbt> [after.nbt] [--contract contract.json] [--site site.json] [--json]
//               (--site: water validity + continuity inflow->outflow, building dry and clear of trees, piers on rock,
//               paths walkable; site.json = { inflow, outflow, building: {from,to}, piers, paths })
//               (always: STRUCTURE — floating blocks, unsupported hanging/mounted blocks, orphans, enclosed/invisible cells)
//   mcd info    <file.nbt> [--version v]
//   mcd convert <in> <out>   structure .nbt <-> Litematica .litematic, by extension (every command also reads .litematic)
//   mcd blocks  [--version v] [--grep pattern]        valid block ids for a version
//   mcd states  <block> [--version v]                  valid state properties/values for a block
//   mcd new     <build.mjs> [--from in.nbt] [--size x,y,z] [--out out.nbt]   scaffold a generator script
//   mcd concept "<subject>" --out c.png [--size s] [--palette p] [--provider codex|gemini] [--ref img]... [--model m] [--raw]
//               builder reference sheet: Codex CLI image_gen (ChatGPT plan, no key) or Gemini (GEMINI_API_KEY);
//               default: codex if installed, else gemini; --ref attaches reference images (codex)
//   mcd assets  [--version v]                          fetch/cache the client jar ahead of time
//   mcd faces   <file.nbt> [--face north,east,...] [--plain]   each face as a rows x columns block map + depth map (seen
//               from outside); --plain adds a map of the plain cells treatments may write (* = already crafted)
//   mcd features <file.nbt> [--face n|e|s|w|up] [--kind k] [--top N] [--json]   the exterior features detailing works on
//   mcd detail  <in.nbt> <out.nbt> (--plan plan.txt | --op "cornice F3" ...) [--json]   apply detailing operations
//   mcd detail  --vocabulary                            list the detailing operations
//   mcd roof    <in.nbt> <out.nbt> --preset cottage|shop|townhouse|civic|temple|granary|modern|barn|teahouse|tower-cap|lantern-cap|church|workshop|desert|cafe [--front n] [flags override]
//   mcd roof    <in.nbt> <out.nbt> --style mansard [--pitch steep] [--eave cornice] [--material deepslate_tiles]
//               [--trim m] [--overhang n] [--ridge crest] [--dormers 2:e[:gable]] [--pediment n] [--tower x,z,w,h,lantern]
//               [--chimney x,z] [--keep x0,y0,z0,x1,y1,z1] [--spec roof.json] [--json]    re-roof an existing build
//               roof guard rails (put flags AFTER the file names): --dry-run (report only, write nothing)  --strict (exit 2 on any
//               warning)  --texture <palette>|none  --overhang n | n,s,e,w  --no-contrast   (the last three: none/0/off need
//               --why "<reason citing the concept>"); the roof report and warnings print after every run
//   mcd roof    <in.nbt> --detect                       print the detected eave and footprint, change nothing
//   mcd paint   <in.nbt> <out.nbt> --rules rules.txt [--face north,west,roof] [--json]   apply face-map detailing rules
//               (the detail language: skills/minecraft-design/references/detail-language.md; --face = the list the maps
//               were printed with, so the legend letters match); a rule writes only to plain cells unless it ends in force
//   mcd card    <file.nbt> --out card.png [--tiles dir] [--front n] [--layout eye] [--reuse]   render + compose the review card;
//               {"card","tiles","views"} (eye: only what a player sees from the ground)
//
// Version: --version, else $MCD_VERSION, else the structure file's DataVersion, else the latest release.
import { writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, join, resolve, relative } from "node:path";
import { fileURLToPath } from "node:url";
import { spawnSync } from "node:child_process";
import { load, versionOfDataVersion } from "../src/structure.mjs";
import { Assets } from "../src/assets.mjs";
import { walkReport } from "../src/rooms.mjs";
import { lightMaps, lightText } from "../src/light.mjs";
import { lookSheet, compareSheets, roomSheet } from "../src/render/views.mjs";
import { encodePng } from "../src/png.mjs";
import { functionalCells, loadContract, functionReport, flatFields, circulation, siteReport, structureReport } from "../src/check.mjs";
import { features, describe, applyOps, VOCABULARY, faceMaps, faceMapText } from "../src/detail.mjs";
import { applyDetail } from "../src/detail-lang.mjs";
import { plainMaps } from "../src/treatments.mjs";
import { reroof, detectEave, ROOF_STYLES, ROOF_PRESETS } from "../src/roofs.mjs";
import { readFileSync } from "node:fs";
import { card } from "../src/card.mjs";
import { reviewRoof } from "../src/roof-review.mjs";
import { codexImage } from "../src/codex-image.mjs";
import { closeupTiles, zoomTile, tileRows } from "../src/inspect-views.mjs";
import { diffGrids, diffViews } from "../src/inspect-diff.mjs";
import { paletteReport, paletteText } from "../src/inspect-palette.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const cmd = args.shift();
const flags = {}, pos = [], eyes = [];
for (let i = 0; i < args.length; i++) {
  const a = args[i];
  if (!a.startsWith("--")) { pos.push(a); continue; }
